begin;
select no_plan();
reset role;
set local role anon;
set local request.jwt.claim.sub = '';
set local request.jwt.claims = '{"sub":"","role":"anon"}';
select throws_ok($$select * from app.audit_log$$, '42501', 'permission denied for schema app', 'anon: app.audit_log unreadable (DB-08)');
select throws_ok($$select * from app.devices$$, '42501', 'permission denied for schema app', 'anon: app.devices unreadable (DB-08)');
select throws_ok($$select * from app.staff_roles$$, '42501', 'permission denied for schema app', 'anon: app.staff_roles unreadable (DB-08)');
select throws_ok($$select * from app.provider_health$$, '42501', 'permission denied for schema app', 'anon: app.provider_health unreadable (DB-08)');
select throws_ok($$select * from app.provider_calls$$, '42501', 'permission denied for schema app', 'anon: app.provider_calls unreadable (DB-08)');
select throws_ok($$select * from app.likes$$, '42501', 'permission denied for schema app', 'anon: app.likes unreadable (DB-08)');
select throws_ok($$select * from app.play_events$$, '42501', 'permission denied for schema app', 'anon: app.play_events unreadable (DB-08)');
select throws_ok($$select * from app.flags$$, '42501', 'permission denied for schema app', 'anon: app.flags unreadable (DB-08)');
select throws_ok($$select * from app.cost_counters$$, '42501', 'permission denied for schema app', 'anon: app.cost_counters unreadable (DB-08)');
select throws_ok($$select * from app.rate_limits$$, '42501', 'permission denied for schema app', 'anon: app.rate_limits unreadable (DB-08)');
select throws_ok($$select * from app.data_requests$$, '42501', 'permission denied for schema app', 'anon: app.data_requests unreadable (DB-08)');
select throws_ok($$select * from app.moderation_decisions$$, '42501', 'permission denied for schema app', 'anon: app.moderation_decisions unreadable (DB-08)');
select throws_ok($$select * from app.reports$$, '42501', 'permission denied for schema app', 'anon: app.reports unreadable (DB-08)');
select throws_ok($$select * from app.moderation_cases$$, '42501', 'permission denied for schema app', 'anon: app.moderation_cases unreadable (DB-08)');
select throws_ok($$select * from app.moderation_actions$$, '42501', 'permission denied for schema app', 'anon: app.moderation_actions unreadable (DB-08)');
select throws_ok($$select * from app.appeals$$, '42501', 'permission denied for schema app', 'anon: app.appeals unreadable (DB-08)');
select throws_ok($$select * from restricted.moderation_evidence$$, '42501', 'permission denied for schema restricted', 'DB-07 anon: evidence unreadable');
select is((select count(*) from public.models), 6::bigint, 'anon: catalogue models readable and seeded');
select is((select count(*) from public.model_prices), 9::bigint, 'anon: catalogue model_prices readable and seeded');
select is((select count(*) from public.model_languages), 4::bigint, 'anon: catalogue model_languages readable and seeded');
reset role;
set local role authenticated;
set local request.jwt.claim.sub = '';
set local request.jwt.claims = '{"sub":"","role":"authenticated"}';
select throws_ok($$select * from app.audit_log$$, '42501', 'permission denied for schema app', 'authenticated: app.audit_log unreadable (DB-08)');
select throws_ok($$select * from app.devices$$, '42501', 'permission denied for schema app', 'authenticated: app.devices unreadable (DB-08)');
select throws_ok($$select * from app.staff_roles$$, '42501', 'permission denied for schema app', 'authenticated: app.staff_roles unreadable (DB-08)');
select throws_ok($$select * from app.provider_health$$, '42501', 'permission denied for schema app', 'authenticated: app.provider_health unreadable (DB-08)');
select throws_ok($$select * from app.provider_calls$$, '42501', 'permission denied for schema app', 'authenticated: app.provider_calls unreadable (DB-08)');
select throws_ok($$select * from app.likes$$, '42501', 'permission denied for schema app', 'authenticated: app.likes unreadable (DB-08)');
select throws_ok($$select * from app.play_events$$, '42501', 'permission denied for schema app', 'authenticated: app.play_events unreadable (DB-08)');
select throws_ok($$select * from app.flags$$, '42501', 'permission denied for schema app', 'authenticated: app.flags unreadable (DB-08)');
select throws_ok($$select * from app.cost_counters$$, '42501', 'permission denied for schema app', 'authenticated: app.cost_counters unreadable (DB-08)');
select throws_ok($$select * from app.rate_limits$$, '42501', 'permission denied for schema app', 'authenticated: app.rate_limits unreadable (DB-08)');
select throws_ok($$select * from app.data_requests$$, '42501', 'permission denied for schema app', 'authenticated: app.data_requests unreadable (DB-08)');
select throws_ok($$select * from app.moderation_decisions$$, '42501', 'permission denied for schema app', 'authenticated: app.moderation_decisions unreadable (DB-08)');
select throws_ok($$select * from app.reports$$, '42501', 'permission denied for schema app', 'authenticated: app.reports unreadable (DB-08)');
select throws_ok($$select * from app.moderation_cases$$, '42501', 'permission denied for schema app', 'authenticated: app.moderation_cases unreadable (DB-08)');
select throws_ok($$select * from app.moderation_actions$$, '42501', 'permission denied for schema app', 'authenticated: app.moderation_actions unreadable (DB-08)');
select throws_ok($$select * from app.appeals$$, '42501', 'permission denied for schema app', 'authenticated: app.appeals unreadable (DB-08)');
select throws_ok($$select * from restricted.moderation_evidence$$, '42501', 'permission denied for schema restricted', 'DB-07 authenticated: evidence unreadable');
select is((select count(*) from public.models), 6::bigint, 'authenticated: catalogue models readable and seeded');
select is((select count(*) from public.model_prices), 9::bigint, 'authenticated: catalogue model_prices readable and seeded');
select is((select count(*) from public.model_languages), 4::bigint, 'authenticated: catalogue model_languages readable and seeded');
reset role;
select is((select count(*) from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname in ('public','app','restricted') and c.relkind = 'r' and not c.relrowsecurity), 0::bigint, 'RLS enabled in all application schemas');
select is((select array_agg(schemaname::text || '.' || tablename::text order by tablename) from pg_publication_tables where pubname = 'supabase_realtime'),
  array['public.generation_jobs', 'public.notifications'], 'Realtime contains exactly jobs and notifications');
select is((select count(*) from public.models where is_mock and adapter = id), 6::bigint, 'six mock adapters seeded');
select is((select array_agg(model_id || ':' || language || ':' || status order by model_id, language) from public.model_languages),
  array['mock-music-a:en:verified', 'mock-music-a:tr:unverified', 'mock-music-b:en:verified', 'mock-music-b:tr:verified'], 'language statuses exact');
select is((select count(*) from app.staff_roles where user_id = '00000000-0000-4000-8000-000000000004' and role = 'admin'), 1::bigint, 'local staff admin seeded');
select ok((select is_adult and status = 'active' from public.profiles where id = '00000000-0000-4000-8000-000000000004'), 'local staff adult and active');
select ok((select email = 'staff@example.test' and email_confirmed_at is not null and coalesce(encrypted_password, '') = '' from auth.users where id = '00000000-0000-4000-8000-000000000004'), 'staff confirmed without password');
select is((select array_agg(key || ':' || value::text order by key) from app.flags),
  array['block_cooldown_seconds:3600', 'block_cooldown_threshold:3', 'block_suspend_threshold:6', 'block_window_seconds:86400', 'music_queue_concurrency:4', 'per_user_concurrency:2'], 'documented flags seeded exactly');
select is((select count(*) from pg_class c join pg_namespace n on n.oid = c.relnamespace cross join (values ('anon'), ('authenticated')) roles(name) where n.nspname in ('app','restricted') and c.relkind in ('r','v') and has_any_column_privilege(roles.name, c.oid, 'SELECT')), 0::bigint, 'no client column or table read grant anywhere internal');
select is((select count(*) from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname in ('public','app','restricted') and c.relkind = 'r' and c.relname <> 'audit_log' and not (has_table_privilege('service_role', c.oid, 'SELECT') and has_table_privilege('service_role', c.oid, 'INSERT') and has_table_privilege('service_role', c.oid, 'UPDATE') and has_table_privilege('service_role', c.oid, 'DELETE'))), 0::bigint, 'backend receives CRUD on all new tables');
select * from finish();
rollback;
